tool_schemas.implementation:
def get_hist_data(symbol, interval=None, interval_multiplier=None, start_date=None, end_date=None, adjust=None, source=None, indicators_list=None, recent_n=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Defaults
    if interval is None: interval = "day"
    if interval_multiplier is None: interval_multiplier = 1
    if start_date is None: start_date = "1970-01-01"
    if end_date is None: end_date = "2030-12-31"
    if adjust is None: adjust = "none"
    if source is None: source = "eastmoney"
    if recent_n is None: recent_n = 100

    # Helpers
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_date(s):
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except Exception:
            return False

    def _record_call(api_key_id, instrument_id, symbol_in, status, cache_hit, upstream_latency_ms=None, error_message=None, recent_n_used=None):
        tool_calls = _load("tool_calls.json")
        call_id = _new_id("tc")
        row = {
            "id": call_id,
            "api_key_id": api_key_id,
            "tool_name": "get_hist_data",
            "instrument_id": instrument_id,
            "symbol": symbol_in,
            "source": source,
            "interval": interval,
            "interval_multiplier": interval_multiplier,
            "start_date": start_date,
            "end_date": end_date,
            "adjust": adjust,
            "indicators_list": indicators_list,
            "recent_n": recent_n_used,
            "status": status,
            "cache_hit": bool(cache_hit),
            "upstream_latency_ms": upstream_latency_ms,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)
        return call_id

    def _transition(call_id, to_status, error_message=None, upstream_latency_ms=None, cache_hit=None):
        tool_calls = _load("tool_calls.json")
        idx = next((i for i, r in enumerate(tool_calls) if r.get("id") == call_id), None)
        if idx is None:
            return False
        cur = tool_calls[idx].get("status")
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        if to_status not in allowed.get(cur, []):
            return False
        tool_calls[idx]["status"] = to_status
        tool_calls[idx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if upstream_latency_ms is not None:
            tool_calls[idx]["upstream_latency_ms"] = upstream_latency_ms
        if cache_hit is not None:
            tool_calls[idx]["cache_hit"] = bool(cache_hit)
        if to_status == "failed":
            tool_calls[idx]["error_message"] = error_message or "upstream error"
        else:
            tool_calls[idx]["error_message"] = None
        _save("tool_calls.json", tool_calls)
        return True

    def _pick_api_key_and_enforce_limits():
        api_keys = _load("api_keys.json")
        active = [k for k in api_keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available")
        # choose a key that is currently under rpm/day limits (based on existing tool_calls)
        tool_calls = _load("tool_calls.json")
        now_dt = datetime.datetime.utcnow()
        window_min = now_dt - datetime.timedelta(seconds=60)
        window_day = now_dt - datetime.timedelta(days=1)
        def _dt(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None
        for k in active:
            kid = k.get("id")
            rpm = int(k.get("requests_per_minute", 1))
            rpd = int(k.get("requests_per_day", 1))
            c_min = 0
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                ct = _dt(c.get("created_at", ""))
                if not ct:
                    continue
                if ct >= window_day:
                    c_day += 1
                    if ct >= window_min:
                        c_min += 1
            if c_min >= rpm:
                continue
            if c_day >= rpd:
                continue
            return k, None

        # If all active keys are over limits, decide which error dominates (rate vs quota)
        # If any key is below daily but over rpm -> RATE_LIMIT else QUOTA_EXCEEDED
        any_below_day = False
        for k in active:
            kid = k.get("id")
            rpd = int(k.get("requests_per_day", 1))
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                # day
                try:
                    ct = datetime.datetime.fromisoformat(c.get("created_at", "").rstrip("Z"))
                except Exception:
                    continue
                if ct >= window_day:
                    c_day += 1
            if c_day < rpd:
                any_below_day = True
                break
        if any_below_day:
            return None, _err("RATE_LIMIT", "Rate limit exceeded")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Validate inputs
    if not isinstance(symbol, str) or not (1 <= len(symbol) <= 32):
        # record failed call (no instrument resolution)
        key, e = _pick_api_key_and_enforce_limits()
        api_key_id = key["id"] if key else None
        call_id = _record_call(api_key_id, None, symbol if isinstance(symbol, str) else None, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid symbol")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string length 1..32")

    if interval not in {"minute", "hour", "day", "week", "month", "year"}:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid interval")
        return _err("VALIDATION_ERROR", "Invalid interval")
    if not isinstance(interval_multiplier, int) or interval_multiplier < 1:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid interval_multiplier")
        return _err("VALIDATION_ERROR", "interval_multiplier must be an integer >= 1")
    if adjust not in {"none", "qfq", "hfq"}:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid adjust")
        return _err("VALIDATION_ERROR", "Invalid adjust")
    if source not in {"eastmoney", "eastmoney_direct", "sina"}:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid source")
        return _err("VALIDATION_ERROR", "Invalid source")
    if not isinstance(start_date, str) or not isinstance(end_date, str) or not _parse_date(start_date) or not _parse_date(end_date):
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid date format")
        return _err("VALIDATION_ERROR", "start_date and end_date must be YYYY-MM-DD strings")
    if start_date > end_date:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "start_date after end_date")
        return _err("VALIDATION_ERROR", "start_date must be <= end_date")
    if indicators_list is not None:
        if not isinstance(indicators_list, list) or any(not isinstance(x, str) for x in indicators_list):
            key, e = _pick_api_key_and_enforce_limits()
            if e: return e
            call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
            _transition(call_id, "failed", "Invalid indicators_list")
            return _err("VALIDATION_ERROR", "indicators_list must be a list of strings or null")
        allowed_inds = {"SMA", "EMA", "RSI", "MACD", "BOLL", "STOCH", "ATR", "CCI", "ADX"}
        bad = [x for x in indicators_list if x not in allowed_inds]
        if bad:
            key, e = _pick_api_key_and_enforce_limits()
            if e: return e
            call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
            _transition(call_id, "failed", "Invalid indicators_list values")
            return _err("VALIDATION_ERROR", "Invalid indicators_list entry", invalid=bad)
    if recent_n is not None and (not isinstance(recent_n, int) or recent_n < 1):
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid recent_n")
        return _err("VALIDATION_ERROR", "recent_n must be null or an integer >= 1")

    # Auth + rate limits
    key, e = _pick_api_key_and_enforce_limits()
    if e:
        return e
    api_key_id = key["id"]

    # Resolve/create instrument
    instruments = _load("instruments.json")
    inst = next((r for r in instruments if r.get("symbol") == symbol), None)
    if inst is None:
        inst_id = _new_id("inst")
        inst = {
            "id": inst_id,
            "symbol": symbol,
            "exchange": None,
            "name": None,
            "security_type": "stock",
            "currency": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    else:
        inst_id = inst.get("id")

    # Create tool_call received
    call_id = _record_call(api_key_id, inst_id, symbol, "received", False, None, None, recent_n)

    # Transition to running
    if not _transition(call_id, "running"):
        return _err("INVALID_TRANSITION", "Cannot transition tool_call to running")

    # Cache lookup
    cache = _load("market_data_cache.json")

    def _same_inds(a, b):
        if a is None and b is None:
            return True
        if isinstance(a, list) and isinstance(b, list):
            return a == b
        return False

    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        as_of = row.get("as_of")
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        try:
            asdt = datetime.datetime.fromisoformat(as_of.rstrip("Z"))
        except Exception:
            return False
        age = (datetime.datetime.utcnow() - asdt).total_seconds()
        return age <= ttl

    matches = []
    for r in cache:
        if r.get("dataset_type") != "hist_bars":
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if r.get("source") != source:
            continue
        if r.get("interval") != interval:
            continue
        if r.get("interval_multiplier") != interval_multiplier:
            continue
        if r.get("adjust") != adjust:
            continue
        if r.get("start_date") != start_date:
            continue
        if r.get("end_date") != end_date:
            continue
        if not _same_inds(r.get("indicators_list"), indicators_list):
            continue
        if _is_fresh(r):
            matches.append(r)

    def _asof_dt(r):
        try:
            return datetime.datetime.fromisoformat(str(r.get("as_of", "")).rstrip("Z"))
        except Exception:
            return datetime.datetime.min

    chosen = None
    if matches:
        chosen = sorted(matches, key=_asof_dt, reverse=True)[0]

    cache_hit = chosen is not None
    upstream_latency_ms = None

    if not cache_hit:
        # "Fetch upstream": create deterministic synthetic bars for offline server
        upstream_t0 = time.time()
        bars = []
        # Generate dates at day granularity for simplicity; include requested interval in payload metadata
        # Keep it bounded for safety
        try:
            sd = datetime.datetime.strptime(start_date, "%Y-%m-%d").date()
            ed = datetime.datetime.strptime(end_date, "%Y-%m-%d").date()
        except Exception:
            _transition(call_id, "failed", "Invalid date parsing in backend")
            return _err("VALIDATION_ERROR", "Invalid date range")

        max_points = 2000
        cur = sd
        i = 0
        base = (abs(hash(symbol)) % 5000) / 10.0 + 10.0
        while cur <= ed and i < max_points:
            # skip weekends for stock-like behaviour
            if cur.weekday() < 5:
                tstr = cur.isoformat()
                o = base + (i % 10) * 0.1
                c = o + ((i % 7) - 3) * 0.05
                h = max(o, c) + 0.08
                l = min(o, c) - 0.08
                v = 100000 + (i * 137) % 50000
                bar = {"time": tstr, "open": round(o, 4), "high": round(h, 4), "low": round(l, 4), "close": round(c, 4), "volume": int(v)}
                bars.append(bar)
                i += 1
            cur = cur + datetime.timedelta(days=1)

        # compute simple indicators
        if indicators_list:
            closes = [b["close"] for b in bars]
            def sma(n):
                out = []
                s = 0.0
                for j, x in enumerate(closes):
                    s += x
                    if j >= n:
                        s -= closes[j-n]
                    out.append(s / n if j >= n-1 else None)
                return out
            def ema(n):
                out = []
                alpha = 2.0 / (n + 1.0)
                e = None
                for x in closes:
                    e = x if e is None else (alpha * x + (1 - alpha) * e)
                    out.append(e)
                return out
            def rsi(n=14):
                out = []
                gains = []
                losses = []
                prev = None
                for x in closes:
                    if prev is None:
                        out.append(None); prev = x; continue
                    ch = x - prev
                    gains.append(max(ch, 0.0))
                    losses.append(max(-ch, 0.0))
                    if len(gains) < n:
                        out.append(None)
                    else:
                        g = sum(gains[-n:]) / n
                        l = sum(losses[-n:]) / n
                        if l == 0:
                            out.append(100.0)
                        else:
                            rs = g / l
                            out.append(100.0 - (100.0 / (1.0 + rs)))
                    prev = x
                return out

            if "SMA" in indicators_list:
                s = sma(14)
                for b, val in zip(bars, s):
                    b["SMA_14"] = None if val is None else round(val, 4)
            if "EMA" in indicators_list:
                e14 = ema(14)
                for b, val in zip(bars, e14):
                    b["EMA_14"] = None if val is None else round(val, 4)
            if "RSI" in indicators_list:
                r14 = rsi(14)
                for b, val in zip(bars, r14):
                    b["RSI_14"] = None if val is None else round(val, 4)
            # Provide placeholders for other indicators if requested
            for ind in indicators_list:
                if ind in {"MACD", "BOLL", "STOCH", "ATR", "CCI", "ADX"}:
                    # Minimal deterministic placeholder columns
                    col = ind
                    for j, b in enumerate(bars):
                        b[col] = round((j % 100) / 10.0, 4)

        upstream_latency_ms = int((time.time() - upstream_t0) * 1000)

        payload_rows = bars
        payload_count = len(payload_rows)

        cache_row = {
            "id": _new_id("cache"),
            "instrument_id": inst_id,
            "dataset_type": "hist_bars",
            "source": source,
            "interval": interval,
            "interval_multiplier": interval_multiplier,
            "adjust": adjust,
            "start_date": start_date,
            "end_date": end_date,
            "indicators_list": indicators_list,
            "as_of": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "ttl_seconds": 300,
            "status": "fresh",
            "payload": payload_rows,
            "payload_row_count": payload_count,
            "created_at": now,
            "updated_at": now,
        }
        cache.append(cache_row)
        _save("market_data_cache.json", cache)
        chosen = cache_row

    # Apply recent_n truncation to most recent rows
    payload = chosen.get("payload")
    if not isinstance(payload, list):
        _transition(call_id, "failed", "Cache payload invalid")
        return _err("CONFLICT", "Cached dataset payload is invalid")
    # assume ascending time; return most recent
    out_rows = payload[-recent_n:] if recent_n is not None else payload[-100:]
    # Update call row with cache_hit/latency already possibly missing on cache hit
    _transition(call_id, "succeeded", upstream_latency_ms=upstream_latency_ms, cache_hit=cache_hit)

    # Update api key last_used_at
    api_keys = _load("api_keys.json")
    for i, r in enumerate(api_keys):
        if r.get("id") == api_key_id:
            if r.get("status") != "active":
                return _err("UNAUTHORIZED", "API key revoked")
            api_keys[i]["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            api_keys[i]["updated_at"] = api_keys[i].get("updated_at") or now
            break
    _save("api_keys.json", api_keys)

    return {
        "tool": "get_hist_data",
        "symbol": symbol,
        "instrument_id": inst_id,
        "source": source,
        "interval": interval,
        "interval_multiplier": interval_multiplier,
        "start_date": start_date,
        "end_date": end_date,
        "adjust": adjust,
        "indicators_list": indicators_list,
        "recent_n": recent_n,
        "cache_hit": cache_hit,
        "as_of": chosen.get("as_of"),
        "data": out_rows,
        "meta": {"returned": len(out_rows), "total_cached_rows": chosen.get("payload_row_count"), "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_realtime_data(symbol=None, source=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if source is None:
        source = "xueqiu"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_api_key_and_enforce_limits():
        api_keys = _load("api_keys.json")
        active = [k for k in api_keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available")
        tool_calls = _load("tool_calls.json")
        now_dt = datetime.datetime.utcnow()
        window_min = now_dt - datetime.timedelta(seconds=60)
        window_day = now_dt - datetime.timedelta(days=1)
        def _dt(ts):
            try:
                return datetime.datetime.fromisoformat(str(ts).rstrip("Z"))
            except Exception:
                return None
        for k in active:
            kid = k.get("id")
            rpm = int(k.get("requests_per_minute", 1))
            rpd = int(k.get("requests_per_day", 1))
            c_min = 0
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                ct = _dt(c.get("created_at", ""))
                if not ct:
                    continue
                if ct >= window_day:
                    c_day += 1
                    if ct >= window_min:
                        c_min += 1
            if c_min < rpm and c_day < rpd:
                return k, None
        any_below_day = False
        for k in active:
            kid = k.get("id")
            rpd = int(k.get("requests_per_day", 1))
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                try:
                    ct = datetime.datetime.fromisoformat(str(c.get("created_at", "")).rstrip("Z"))
                except Exception:
                    continue
                if ct >= window_day:
                    c_day += 1
            if c_day < rpd:
                any_below_day = True
                break
        if any_below_day:
            return None, _err("RATE_LIMIT", "Rate limit exceeded")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    def _record_call(api_key_id, instrument_id, symbol_in, status, cache_hit, upstream_latency_ms=None, error_message=None):
        tool_calls = _load("tool_calls.json")
        call_id = _new_id("tc")
        row = {
            "id": call_id,
            "api_key_id": api_key_id,
            "tool_name": "get_realtime_data",
            "instrument_id": instrument_id,
            "symbol": symbol_in,
            "source": source,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": None,
            "status": status,
            "cache_hit": bool(cache_hit),
            "upstream_latency_ms": upstream_latency_ms,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)
        return call_id

    def _transition(call_id, to_status, error_message=None, upstream_latency_ms=None, cache_hit=None):
        tool_calls = _load("tool_calls.json")
        idx = next((i for i, r in enumerate(tool_calls) if r.get("id") == call_id), None)
        if idx is None:
            return False
        cur = tool_calls[idx].get("status")
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        if to_status not in allowed.get(cur, []):
            return False
        tool_calls[idx]["status"] = to_status
        tool_calls[idx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if upstream_latency_ms is not None:
            tool_calls[idx]["upstream_latency_ms"] = upstream_latency_ms
        if cache_hit is not None:
            tool_calls[idx]["cache_hit"] = bool(cache_hit)
        if to_status == "failed":
            tool_calls[idx]["error_message"] = error_message or "upstream error"
        else:
            tool_calls[idx]["error_message"] = None
        _save("tool_calls.json", tool_calls)
        return True

    # Validate
    if source not in {"xueqiu", "eastmoney", "eastmoney_direct"}:
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, symbol if isinstance(symbol, str) else None, "received", False, None, None)
        _transition(call_id, "failed", "Invalid source")
        return _err("VALIDATION_ERROR", "Invalid source")

    if symbol is not None and (not isinstance(symbol, str) or not (1 <= len(symbol) <= 32)):
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, None, "received", False, None, None)
        _transition(call_id, "failed", "Invalid symbol")
        return _err("VALIDATION_ERROR", "symbol must be null or a non-empty string length 1..32")

    # Auth + rate limits
    key, e = _pick_api_key_and_enforce_limits()
    if e:
        return e
    api_key_id = key["id"]

    instrument_id = None
    resolved_symbol = symbol

    # Resolve/create instrument unless symbol is null
    if symbol is not None:
        instruments = _load("instruments.json")
        inst = next((r for r in instruments if r.get("symbol") == symbol), None)
        if inst is None:
            inst_id = _new_id("inst")
            inst = {
                "id": inst_id,
                "symbol": symbol,
                "exchange": None,
                "name": None,
                "security_type": "stock",
                "currency": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            instruments.append(inst)
            _save("instruments.json", instruments)
        instrument_id = inst.get("id")

    call_id = _record_call(api_key_id, instrument_id, resolved_symbol, "received", False, None, None)
    if not _transition(call_id, "running"):
        return _err("INVALID_TRANSITION", "Cannot transition tool_call to running")

    cache = _load("market_data_cache.json")
    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        try:
            asdt = datetime.datetime.fromisoformat(str(row.get("as_of", "")).rstrip("Z"))
        except Exception:
            return False
        return (datetime.datetime.utcnow() - asdt).total_seconds() <= ttl

    matches = []
    for r in cache:
        if r.get("dataset_type") != "realtime_quote":
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("source") != source:
            continue
        if _is_fresh(r):
            matches.append(r)
    def _asof_dt(r):
        try:
            return datetime.datetime.fromisoformat(str(r.get("as_of", "")).rstrip("Z"))
        except Exception:
            return datetime.datetime.min
    chosen = sorted(matches, key=_asof_dt, reverse=True)[0] if matches else None

    cache_hit = chosen is not None
    upstream_latency_ms = None

    if not cache_hit:
        upstream_t0 = time.time()
        # synthetic quote snapshot
        mid = (abs(hash((symbol, source))) % 5000) / 10.0 + 10.0 if symbol is not None else 100.0
        payload = {
            "symbol": symbol,
            "source": source,
            "timestamp": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "last": round(mid, 4),
            "open": round(mid - 0.5, 4),
            "high": round(mid + 0.8, 4),
            "low": round(mid - 0.9, 4),
            "volume": int(1000000 + (abs(hash(symbol)) % 100000)) if symbol is not None else int(50000000),
            "market_snapshot": symbol is None,
        }
        upstream_latency_ms = int((time.time() - upstream_t0) * 1000)
        cache_row = {
            "id": _new_id("cache"),
            "instrument_id": instrument_id,  # may be None for market snapshot
            "dataset_type": "realtime_quote",
            "source": source,
            "interval": None,
            "interval_multiplier": None,
            "adjust": None,
            "start_date": None,
            "end_date": None,
            "indicators_list": None,
            "as_of": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "ttl_seconds": 10,
            "status": "fresh",
            "payload": payload,
            "payload_row_count": 1,
            "created_at": now,
            "updated_at": now,
        }
        cache.append(cache_row)
        _save("market_data_cache.json", cache)
        chosen = cache_row

    _transition(call_id, "succeeded", upstream_latency_ms=upstream_latency_ms, cache_hit=cache_hit)

    api_keys = _load("api_keys.json")
    for i, r in enumerate(api_keys):
        if r.get("id") == api_key_id:
            if r.get("status") != "active":
                return _err("UNAUTHORIZED", "API key revoked")
            api_keys[i]["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("api_keys.json", api_keys)

    return {
        "tool": "get_realtime_data",
        "symbol": symbol,
        "instrument_id": instrument_id,
        "source": source,
        "cache_hit": cache_hit,
        "as_of": chosen.get("as_of"),
        "data": chosen.get("payload"),
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def get_news_data(symbol, recent_n=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if recent_n is None:
        recent_n = 10

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _pick_api_key_and_enforce_limits():
        api_keys = _load("api_keys.json")
        active = [k for k in api_keys if k.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API key available")
        tool_calls = _load("tool_calls.json")
        now_dt = datetime.datetime.utcnow()
        window_min = now_dt - datetime.timedelta(seconds=60)
        window_day = now_dt - datetime.timedelta(days=1)
        def _dt(ts):
            try:
                return datetime.datetime.fromisoformat(str(ts).rstrip("Z"))
            except Exception:
                return None
        for k in active:
            kid = k.get("id")
            rpm = int(k.get("requests_per_minute", 1))
            rpd = int(k.get("requests_per_day", 1))
            c_min = 0
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                ct = _dt(c.get("created_at", ""))
                if not ct:
                    continue
                if ct >= window_day:
                    c_day += 1
                    if ct >= window_min:
                        c_min += 1
            if c_min < rpm and c_day < rpd:
                return k, None
        any_below_day = False
        for k in active:
            kid = k.get("id")
            rpd = int(k.get("requests_per_day", 1))
            c_day = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                try:
                    ct = datetime.datetime.fromisoformat(str(c.get("created_at", "")).rstrip("Z"))
                except Exception:
                    continue
                if ct >= window_day:
                    c_day += 1
            if c_day < rpd:
                any_below_day = True
                break
        if any_below_day:
            return None, _err("RATE_LIMIT", "Rate limit exceeded")
        return None, _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    def _record_call(api_key_id, instrument_id, status, cache_hit, upstream_latency_ms=None, error_message=None, recent_n_used=None):
        tool_calls = _load("tool_calls.json")
        call_id = _new_id("tc")
        row = {
            "id": call_id,
            "api_key_id": api_key_id,
            "tool_name": "get_news_data",
            "instrument_id": instrument_id,
            "symbol": symbol,
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": recent_n_used,
            "status": status,
            "cache_hit": bool(cache_hit),
            "upstream_latency_ms": upstream_latency_ms,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)
        return call_id

    def _transition(call_id, to_status, error_message=None, upstream_latency_ms=None, cache_hit=None):
        tool_calls = _load("tool_calls.json")
        idx = next((i for i, r in enumerate(tool_calls) if r.get("id") == call_id), None)
        if idx is None:
            return False
        cur = tool_calls[idx].get("status")
        allowed = {"received": ["running", "failed"], "running": ["succeeded", "failed"], "succeeded": [], "failed": []}
        if to_status not in allowed.get(cur, []):
            return False
        tool_calls[idx]["status"] = to_status
        tool_calls[idx]["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        if upstream_latency_ms is not None:
            tool_calls[idx]["upstream_latency_ms"] = upstream_latency_ms
        if cache_hit is not None:
            tool_calls[idx]["cache_hit"] = bool(cache_hit)
        if to_status == "failed":
            tool_calls[idx]["error_message"] = error_message or "upstream error"
        else:
            tool_calls[idx]["error_message"] = None
        _save("tool_calls.json", tool_calls)
        return True

    # Validate
    if not isinstance(symbol, str) or not (1 <= len(symbol) <= 32):
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid symbol")
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string length 1..32")
    if recent_n is not None and (not isinstance(recent_n, int) or recent_n < 1):
        key, e = _pick_api_key_and_enforce_limits()
        if e: return e
        call_id = _record_call(key["id"], None, "received", False, None, None, recent_n)
        _transition(call_id, "failed", "Invalid recent_n")
        return _err("VALIDATION_ERROR", "recent_n must be null or an integer >= 1")

    key, e = _pick_api_key_and_enforce_limits()
    if e: return e
    api_key_id = key["id"]

    # Resolve/create instrument
    instruments = _load("instruments.json")
    inst = next((r for r in instruments if r.get("symbol") == symbol), None)
    if inst is None:
        inst_id = _new_id("inst")
        inst = {
            "id": inst_id,
            "symbol": symbol,
            "exchange": None,
            "name": None,
            "security_type": "stock",
            "currency": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    inst_id = inst.get("id")

    call_id = _record_call(api_key_id, inst_id, "received", False, None, None, recent_n)
    if not _transition(call_id, "running"):
        return _err("INVALID_TRANSITION", "Cannot transition tool_call to running")

    cache = _load("market_data_cache.json")
    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        try:
            asdt = datetime.datetime.fromisoformat(str(row.get("as_of", "")).rstrip("Z"))
        except Exception:
            return False
        return (datetime.datetime.utcnow() - asdt).total_seconds() <= ttl

    matches = []
    for r in cache:
        if r.get("dataset_type") != "news":
            continue
        if r.get("instrument_id") != inst_id:
            continue
        if _is_fresh(r):
            matches.append(r)

    def _asof_dt(r):
        try:
            return datetime.datetime.fromisoformat(str(r.get("as_of", "")).rstrip("Z"))
        except Exception:
            return datetime.datetime.min

    chosen = sorted(matches, key=_asof_dt, reverse=True)[0] if matches else None
    cache_hit = chosen is not None
    upstream_latency_ms = None

    if not cache_hit:
        upstream_t0 = time.time()
        # deterministic synthetic news
        items = []
        base = abs(hash(symbol)) % 10000
        for i in range(25):
            ts = (datetime.datetime.utcnow() - datetime.timedelta(hours=i)).replace(microsecond=0).isoformat() + "Z"
            items.append({
                "id": f"news_{symbol}_{base+i}",
                "published_at": ts,
                "title": f"{symbol} headline {i}",
                "summary": f"Synthetic news item {i} for {symbol}.",
                "url": f"https://example.invalid/{symbol}/{base+i}",
                "source": "offline",
            })
        upstream_latency_ms = int((time.time() - upstream_t0) * 1000)
        cache_row = {
            "id": _new_id("cache"),
            "instrument_id": inst_id,
            "dataset_type": "news",
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "adjust": None,
            "start_date": None,
            "end_date": None,
            "indicators_list": None,
            "as_of": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "ttl_seconds": 300,
            "status": "fresh",
            "payload": items,
            "payload_row_count": len(items),
            "created_at": now,
            "updated_at": now,
        }
        cache.append(cache_row)
        _save("market_data_cache.json", cache)
        chosen = cache_row

    payload = chosen.get("payload")
    if not isinstance(payload, list):
        _transition(call_id, "failed", "Cache payload invalid")
        return _err("CONFLICT", "Cached dataset payload is invalid")
    out_items = payload[:recent_n]

    if len(out_items) == 0:
        _transition(call_id, "failed", "No news available")
        return _err("NOT_FOUND", "No news items available for this symbol")

    _transition(call_id, "succeeded", upstream_latency_ms=upstream_latency_ms, cache_hit=cache_hit)

    api_keys = _load("api_keys.json")
    for i, r in enumerate(api_keys):
        if r.get("id") == api_key_id:
            if r.get("status") != "active":
                return _err("UNAUTHORIZED", "API key revoked")
            api_keys[i]["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("api_keys.json", api_keys)

    return {
        "tool": "get_news_data",
        "symbol": symbol,
        "instrument_id": inst_id,
        "recent_n": recent_n,
        "cache_hit": cache_hit,
        "as_of": chosen.get("as_of"),
        "data": out_items,
        "meta": {"returned": len(out_items), "total_cached_items": chosen.get("payload_row_count"), "latency_ms": int((time.time() - t0) * 1000)},
    }

