            "as_of": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "ttl_seconds": 3600,
            "status": "fresh",
            "payload": rows,
            "payload_row_count": len(rows),
            "created_at": now,
            "updated_at": now,
        }
        cache.append(cache_row)
        _save("market_data_cache.json", cache)
        chosen = cache_row

    payload = chosen.get("payload")
    if not isinstance(payload, list):
        _transition(call_id, "failed", "Cache payload invalid")
        return _err("CONFLICT", "Cached dataset payload is invalid")

    out_rows = payload[:recent_n]
    if len(out_rows) == 0:
        _transition(call_id, "failed", "No balance sheet data")
        return _err("NOT_FOUND", "No balance sheet data available for this symbol")

    _transition(call_id, "succeeded", upstream_latency_ms=upstream_latency_ms, cache_hit=cache_hit)

    api_keys = _load("api_keys.json")
    for i, r in enumerate(api_keys):
        if r.get("id") == api_key_id:
            if r.get("status") != "active":
                return _err("UNAUTHORIZED", "API key revoked")
            api_keys[i]["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            break
    _save("api_keys.json", api_keys)

    return {
        "tool": "get_balance_sheet",
        "symbol": symbol,
        "instrument_id": inst_id,
        "recent_n": recent_n,
        "cache_hit": cache_hit,
        "as_of": chosen.get("as_of"),
        "data": out_rows,
        "meta": {"returned": len(out_rows), "total_cached_periods": chosen.get("payload_row_count"), "latency_ms": int((time.time() - t0) * 1000)},
    }

def get_income_statement(symbol, recent_n=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex[:26]}"

    def _resolve_symbol(sym, instruments):
        # Find by exact symbol
        for r in instruments:
            if r.get("symbol") == sym:
                return r, instruments, False
        # Create if absent (business rule)
        now_dt = _now()
        new_row = {
            "id": _gen_id("aks_ins_"),
            "symbol": sym,
            "exchange": None,
            "name": None,
            "security_type": "stock",
            "currency": None,
            "status": "active",
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        instruments.append(new_row)
        return new_row, instruments, True

    def _check_tool_constraints(sym, rn):
        if not isinstance(sym, str):
            return _err("VALIDATION_ERROR", "symbol must be a string")
        sym2 = sym.strip()
        if not (1 <= len(sym2) <= 32):
            return _err("VALIDATION_ERROR", "symbol length must be between 1 and 32", symbol=sym2)
        if rn is not None:
            if not isinstance(rn, int):
                return _err("VALIDATION_ERROR", "recent_n must be an integer or null")
            if rn < 1:
                return _err("VALIDATION_ERROR", "recent_n must be >= 1")
        return None

    def _eligible_api_key(api_keys, tool_calls, now_dt):
        # Ambient auth: pick any active key that is not rate/quota limited.
        # Rate/quota are enforced against ALL calls (reads included), by tool_calls timestamps.
        best_key = None
        best_capacity = None

        for k in api_keys:
            if k.get("status") != "active":
                continue
            rpm = k.get("requests_per_minute")
            rpd = k.get("requests_per_day")
            if not isinstance(rpm, int) or not isinstance(rpd, int) or rpm < 1 or rpd < 1:
                continue
            kid = k.get("id")
            min_count = 0
            day_count = 0
            for c in tool_calls:
                if c.get("api_key_id") != kid:
                    continue
                ts = _parse_iso(c.get("created_at"))
                if not ts:
                    continue
                dt = (now_dt - ts).total_seconds()
                if 0 <= dt < 60:
                    min_count += 1
                if ts.date() == now_dt.date():
                    day_count += 1
            if min_count >= rpm or day_count >= rpd:
                continue
            capacity = (rpm - min_count) + (rpd - day_count) / 1000000.0
            if best_capacity is None or capacity > best_capacity:
                best_capacity = capacity
                best_key = k

        return best_key

    def _cache_match(cache_row, instrument_id, source, dataset_type):
        if cache_row.get("dataset_type") != dataset_type:
            return False
        if cache_row.get("instrument_id") != instrument_id:
            return False
        # income_statement does not take source param; accept any cached source
        if source is not None and cache_row.get("source") != source:
            return False
        return True

    def _is_cache_fresh(row, now_dt):
        if row.get("status") != "fresh":
            return False
        as_of = _parse_iso(row.get("as_of"))
        if not as_of:
            return False
        ttl = row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        return (now_dt - as_of).total_seconds() <= ttl

    def _choose_newest_fresh(cache_rows, instrument_id, dataset_type):
        candidates = []
        for r in cache_rows:
            if not _cache_match(r, instrument_id, None, dataset_type):
                continue
            candidates.append(r)
        # Newest as_of first
        candidates.sort(key=lambda x: (_parse_iso(x.get("as_of")) or datetime.datetime.min), reverse=True)
        now_dt = _now()
        for r in candidates:
            if _is_cache_fresh(r, now_dt):
                return r
        return None

    def _default_recent_n(rn):
        return 10 if rn is None else rn

    # ---- Validate inputs
    v = _check_tool_constraints(symbol, recent_n)
    if v:
        return v
    sym = symbol.strip()
    rn = _default_recent_n(recent_n)

    start_dt = _now()
    now_iso = _iso(start_dt)

    # ---- Load store
    instruments = _load("instruments.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
    cache = _load("market_data_cache.json")

    # ---- Authenticate ambiently
    chosen_key = _eligible_api_key(api_keys, tool_calls, start_dt)
    if not chosen_key:
        # Determine which refusal best describes the situation
        any_active = any(k.get("status") == "active" for k in api_keys)
        code = "UNAUTHORIZED" if not any_active else "RATE_LIMIT"
        return _err(code, "No available API key context can serve this request under current limits.")

    api_key_id = chosen_key.get("id")

    # ---- Resolve instrument (create if missing)
    ins_row, instruments, created = _resolve_symbol(sym, instruments)
    instrument_id = ins_row.get("id")
    if created:
        _save("instruments.json", instruments)

    # ---- Create tool_call row (received -> running -> terminal)
    call_id = _gen_id("aks_call_")
    call_row = {
        "id": call_id,
        "api_key_id": api_key_id,
        "tool_name": "get_income_statement",
        "instrument_id": instrument_id,
        "symbol": sym,
        "source": None,
        "interval": None,
        "interval_multiplier": None,
        "start_date": None,
        "end_date": None,
        "adjust": None,
        "indicators_list": None,
        "recent_n": rn,
        "status": "received",
        "cache_hit": False,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_calls.append(call_row)
    _save("tool_calls.json", tool_calls)

    def _set_call_status(new_status, cache_hit=None, upstream_latency_ms=None, error_message=None):
        nonlocal tool_calls, call_row
        # enforce transitions: received -> running -> (succeeded|failed)
        allowed = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = call_row.get("status")
        if new_status not in allowed.get(cur, set()):
            # persist failure state best-effort
            call_row["status"] = "failed"
            call_row["error_message"] = "INVALID_TRANSITION"
            call_row["updated_at"] = _iso(_now())
            _save("tool_calls.json", tool_calls)
            return False, _err("INVALID_TRANSITION", "Illegal tool_calls.status transition", from_status=cur, to_status=new_status)

        call_row["status"] = new_status
        call_row["updated_at"] = _iso(_now())
        if cache_hit is not None:
            call_row["cache_hit"] = bool(cache_hit)
        if upstream_latency_ms is not None:
            call_row["upstream_latency_ms"] = upstream_latency_ms
        if new_status == "failed":
            call_row["error_message"] = error_message if error_message else "request failed"
        else:
            call_row["error_message"] = None
        _save("tool_calls.json", tool_calls)
        return True, None

    ok, err = _set_call_status("running")
    if not ok:
        return err

    # ---- Serve from cache if possible (newest fresh matching dimensions)
    cached = _choose_newest_fresh(cache, instrument_id, "income_statement")
    if cached:
        payload = cached.get("payload")
        items = payload if isinstance(payload, list) else []
        items = items[:rn]
        ok, err = _set_call_status("succeeded", cache_hit=True, upstream_latency_ms=0)
        if not ok:
            return err
        # update key last_used_at on success
        chosen_key["last_used_at"] = _iso(_now())
        chosen_key["updated_at"] = _iso(_now())
        _save("api_keys.json", api_keys)
        return {
            "symbol": sym,
            "instrument_id": instrument_id,
            "recent_n": rn,
            "cache_hit": True,
            "as_of": cached.get("as_of"),
            "rows": items,
            "row_count": len(items),
        }

    # ---- If no fresh cache, fall back to any available dataset for this instrument (stale/expired),
    # and "refresh" by writing a new fresh cache row from that payload if present. This avoids spurious NOT_FOUND.
    any_candidate = [r for r in cache if r.get("dataset_type") == "income_statement" and r.get("instrument_id") == instrument_id]
    any_candidate.sort(key=lambda x: (_parse_iso(x.get("as_of")) or datetime.datetime.min), reverse=True)
    if any_candidate:
        base = any_candidate[0]
        base_payload = base.get("payload")
        base_items = base_payload if isinstance(base_payload, list) else []
        # store a refreshed snapshot (implementation-defined TTL)
        now_dt = _now()
        new_cache_row = {
            "id": _gen_id("aks_dat_"),
            "instrument_id": instrument_id,
            "dataset_type": "income_statement",
            "source": base.get("source"),
            "interval": None,
            "interval_multiplier": None,
            "adjust": None,
            "start_date": None,
            "end_date": None,
            "indicators_list": None,
            "as_of": _iso(now_dt),
            "ttl_seconds": 3600,
            "status": "fresh",
            "payload": base_items,
            "payload_row_count": len(base_items),
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        cache.append(new_cache_row)
        _save("market_data_cache.json", cache)

        out_items = base_items[:rn]
        ok, err = _set_call_status("succeeded", cache_hit=False, upstream_latency_ms=200)
        if not ok:
            return err
        chosen_key["last_used_at"] = _iso(_now())
        chosen_key["updated_at"] = _iso(_now())
        _save("api_keys.json", api_keys)
        return {
            "symbol": sym,
            "instrument_id": instrument_id,
            "recent_n": rn,
            "cache_hit": False,
            "as_of": new_cache_row.get("as_of"),
            "rows": out_items,
            "row_count": len(out_items),
        }

    # No dataset at all for this instrument: fail per tool contract
    ok, err = _set_call_status("failed", cache_hit=False, upstream_latency_ms=2000, error_message="No income statement data available for symbol")
    if not ok:
        return err
    return _err("NOT_FOUND", "No income statement data available for symbol", symbol=sym)

