    if not isinstance(src, str) or src not in allowed_sources:
        return _err("VALIDATION_ERROR", "source is not accepted by this tool", allowed=sorted(allowed_sources))

    if recent_n is None:
        rn = 10
    else:
        if not isinstance(recent_n, int):
            return _err("VALIDATION_ERROR", "recent_n must be an integer or null")
        if recent_n < 1:
            return _err("VALIDATION_ERROR", "recent_n must be >= 1")
        rn = recent_n

    # ---- Load store
    instruments = _load("instruments.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
