        if cache_row.get("status") != "fresh":
            return False
        as_of = _parse_iso(cache_row.get("as_of"))
        if not as_of:
            return False
        ttl = cache_row.get("ttl_seconds")
        if not isinstance(ttl, int) or ttl < 0:
            return False
        return (_now() - as_of).total_seconds() <= ttl

    # Choose newest fresh cache matching dimensions (instrument_id + dataset_type + source)
    candidates = [r for r in cache if r.get("dataset_type") == "cash_flow" and r.get("instrument_id") == instrument_id and r.get("source") == src]
    candidates.sort(key=lambda x: (_parse_iso(x.get("as_of")) or datetime.datetime.min), reverse=True)
