            "rows": rows,
            "row_count": len(rows),
        }

    # If no fresh cache for requested source, relax by using any cached source for this instrument to avoid
    # false NOT_FOUND due to a mismatched context; then "refresh" a new cache row for the requested source.
    any_src = [r for r in cache if r.get("dataset_type") == "cash_flow" and r.get("instrument_id") == instrument_id]
    any_src.sort(key=lambda x: (_parse_iso(x.get("as_of")) or datetime.datetime.min), reverse=True)
