            "as_of": new_cache_row.get("as_of"),
            "rows": out_rows,
            "row_count": len(out_rows),
        }

    ok, err = _set_call_status("failed", cache_hit=False, upstream_latency_ms=2000, error_message="No cash flow data available for symbol/source")
    if not ok:
        return err
    return _err("NOT_FOUND", "No cash flow data available for symbol/source", symbol=sym, source=src)

