    now_iso = now.isoformat() + "Z"

    allowed_sources = {"eastmoney", "eastmoney_direct", "sina", "xueqiu"}
    src = "eastmoney" if source is None else source
    if not isinstance(src, str) or src not in allowed_sources:
        return _err("VALIDATION_ERROR", "source must be one of the supported providers", allowed=list(sorted(allowed_sources)))

    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    def _is_within_minute(ts, ref):
        return ts is not None and 0 <= (ref - ts).total_seconds() < 60

    def _is_within_day(ts, ref):
        return ts is not None and ts.date() == ref.date()

    def _check_limits_for_key(krow):
        if krow.get("status") != "active":
            return False, None
        kid = krow.get("id")
        rpm = krow.get("requests_per_minute")
        rpd = krow.get("requests_per_day")
        if not isinstance(rpm, int) or not isinstance(rpd, int) or rpm < 1 or rpd < 1:
            return False, None
        calls = [c for c in tool_calls if c.get("api_key_id") == kid and c.get("status") == "succeeded"]
        minute_count = 0
        day_count = 0
        for c in calls:
            ts = _parse_iso(c.get("created_at"))
            if _is_within_minute(ts, now):
                minute_count += 1
            if _is_within_day(ts, now):
                day_count += 1
        if minute_count >= rpm:
            return False, "RATE_LIMIT"
        if day_count >= rpd:
            return False, "QUOTA_EXCEEDED"
        return True, None

    chosen_key = None
    limit_block = None
    for k in api_keys:
        ok, block = _check_limits_for_key(k)
        if ok:
            chosen_key = k
            break
        if block in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
            limit_block = block if limit_block != "QUOTA_EXCEEDED" else limit_block

    if chosen_key is None:
        if limit_block == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
        if limit_block == "RATE_LIMIT":
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return _err("UNAUTHORIZED", "No active API key available to serve this request")

    api_key_id = chosen_key.get("id")

    def _new_call_id():
        return "call_" + uuid.uuid4().hex

    call_row = {
        "id": _new_call_id(),
        "api_key_id": api_key_id,
        "tool_name": "get_time_info",
        "instrument_id": None,
        "symbol": None,
        "source": None,  # constraint: for get_time_info source is null
        "interval": None,
        "interval_multiplier": None,
        "start_date": None,
        "end_date": None,
        "adjust": None,
        "indicators_list": None,
        "recent_n": None,
        "status": "received",
        "cache_hit": False,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_calls.append(call_row)
    _save("tool_calls.json", tool_calls)

    def _transition(call_id, new_status, error_message=None, cache_hit=None, upstream_latency_ms=None):
        nonlocal tool_calls
        allowed = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        for c in tool_calls:
            if c.get("id") == call_id:
                cur = c.get("status")
                if new_status not in allowed.get(cur, set()):
                    return False, _err("INVALID_TRANSITION", f"Illegal tool_calls.status transition {cur} -> {new_status}")
                c["status"] = new_status
                c["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                if cache_hit is not None:
                    c["cache_hit"] = bool(cache_hit)
                if upstream_latency_ms is not None:
                    if not (isinstance(upstream_latency_ms, int) and upstream_latency_ms >= 0):
                        return False, _err("VALIDATION_ERROR", "upstream_latency_ms must be an integer >= 0")
                    c["upstream_latency_ms"] = upstream_latency_ms
                if new_status == "failed":
                    c["error_message"] = error_message if isinstance(error_message, str) and error_message else "Request failed"
                else:
                    c["error_message"] = None
                _save("tool_calls.json", tool_calls)
                return True, c
        return False, _err("NOT_FOUND", "tool_call not found")

    ok, res = _transition(call_row["id"], "running")
    if not ok:
        return res

    cache = _load("market_data_cache.json")

    def _dims_match(row):
        if row.get("dataset_type") != "time_info":
            return False
        if row.get("instrument_id") is not None:
            return False
        if row.get("source") != src:
            return False
        return True

    def _is_fresh(row):
        if row.get("status") != "fresh":
            return False
        as_of = _parse_iso(row.get("as_of"))
        ttl = row.get("ttl_seconds")
        if as_of is None or not isinstance(ttl, int) or ttl < 0:
            return False
        return (now - as_of).total_seconds() <= ttl

    candidates = [r for r in cache if _dims_match(r)]
    candidates.sort(key=lambda r: (_parse_iso(r.get("as_of")) or datetime.datetime.min, _parse_iso(r.get("updated_at")) or datetime.datetime.min), reverse=True)

    chosen_cache = None
    for r in candidates:
        if _is_fresh(r):
            chosen_cache = r
            break

    cache_hit = chosen_cache is not None
    upstream_latency_ms = 0 if cache_hit else 80

    if not cache_hit:
        # Compute time_info offline (implementation-defined)
        # last_trading_day: last weekday (Mon-Fri) in UTC
        last = now.date()
        while last.weekday() >= 5:
            last = last - datetime.timedelta(days=1)
        if now.weekday() == 0 and now.hour < 23:  # simplistic: Monday before "close" still last Friday
            # pick previous Friday
            last = now.date() - datetime.timedelta(days=3)
        last_trading_day = last.isoformat()

        payload = {
            "iso8601": now_iso,
            "timestamp": int(now.replace(tzinfo=datetime.timezone.utc).timestamp()),
            "last_trading_day": last_trading_day,
            "source": src,
        }

        new_row = {
            "id": "cache_" + uuid.uuid4().hex,
            "instrument_id": None,
            "dataset_type": "time_info",
            "source": src,
            "interval": None,
            "interval_multiplier": None,
            "adjust": None,
            "start_date": None,
            "end_date": None,
            "indicators_list": None,
            "as_of": now_iso,
            "ttl_seconds": 10,  # very short
            "status": "fresh",
            "payload": payload,
            "payload_row_count": 1,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cache.append(new_row)
        _save("market_data_cache.json", cache)
        chosen_cache = new_row

    payload = chosen_cache.get("payload")
    if not isinstance(payload, dict) or not payload:
        _transition(call_row["id"], "failed", error_message="Invalid time_info payload")
        return _err("NOT_FOUND", "time_info unavailable")

    ok, res = _transition(call_row["id"], "succeeded", cache_hit=cache_hit, upstream_latency_ms=upstream_latency_ms)
    if not ok:
        return res

    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            k["updated_at"] = k["last_used_at"]
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "source": src,
        "time": payload,
        "meta": {
            "cache_hit": cache_hit,
            "as_of": chosen_cache.get("as_of"),
            "latency_ms": latency_ms,
        },
    }

def list_instruments(api_key, query=None, symbol=None, exchange=None, security_type=None, status=None, page=1, page_size=50, sort="updated_at_desc", **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_iso(dt):
        if not isinstance(dt, str) or not dt:
            return None
        try:
            if dt.endswith("Z"):
                return datetime.datetime.fromisoformat(dt[:-1])
            return datetime.datetime.fromisoformat(dt)
        except Exception:
            return None

    def _auth_key(api_key_value, tool_name):
        api_keys = _load("api_keys.json")
        key_row = None
        if isinstance(api_key_value, str) and api_key_value:
            for r in api_keys:
                if r.get("id") == api_key_value or r.get("key_hash") == api_key_value:
                    key_row = r
                    break
        if not key_row:
            return None, _err("UNAUTHORIZED", "Invalid API key.")
        if key_row.get("status") != "active":
            return None, _err("UNAUTHORIZED", "API key is revoked.")
        # rate limit check (rpm, daily) based on tool_calls log
        tool_calls = _load("tool_calls.json")
        now_dt = _parse_iso(now) or datetime.datetime.utcnow()
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        rpm = key_row.get("requests_per_minute")
        rpd = key_row.get("requests_per_day")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            return None, _err("UNAUTHORIZED", "API key limits misconfigured.")
        cnt_min = 0
        cnt_day = 0
        for c in tool_calls:
            if c.get("api_key_id") != key_row.get("id"):
                continue
            ts = _parse_iso(c.get("created_at"))
            if not ts:
                continue
            if ts >= minute_ago:
                cnt_min += 1
            if ts >= day_ago:
                cnt_day += 1
        if cnt_min >= rpm:
            return None, _err("RATE_LIMIT", "Rate limit exceeded.", limit=rpm, window_seconds=60)
        if cnt_day >= rpd:
            return None, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd, window_seconds=86400)
        return key_row, None

    def _log_call(tool_name, api_key_id, status, latency_ms, **fields):
        tool_calls = _load("tool_calls.json")
        row = {
            "id": _new_id("call"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "instrument_id": fields.get("instrument_id"),
            "symbol": fields.get("symbol"),
            "source": fields.get("source"),
            "interval": fields.get("interval"),
            "interval_multiplier": fields.get("interval_multiplier"),
            "start_date": fields.get("start_date"),
            "end_date": fields.get("end_date"),
            "adjust": fields.get("adjust"),
            "indicators_list": fields.get("indicators_list"),
            "recent_n": fields.get("recent_n"),
            "status": status,
            "cache_hit": bool(fields.get("cache_hit", False)),
            "upstream_latency_ms": fields.get("upstream_latency_ms"),
            "error_message": fields.get("error_message"),
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validate inputs
    if not isinstance(api_key, str) or not api_key:
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string.")
    if query is not None and (not isinstance(query, str) or not query.strip()):
        return _err("VALIDATION_ERROR", "query must be a non-empty string or null.")
    if symbol is not None and (not isinstance(symbol, str) or not symbol.strip()):
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string or null.")
    if exchange is not None and (not isinstance(exchange, str) or not exchange.strip()):
        return _err("VALIDATION_ERROR", "exchange must be a non-empty string or null.")
    if security_type is not None and (not isinstance(security_type, str) or not security_type.strip()):
        return _err("VALIDATION_ERROR", "security_type must be a non-empty string or null.")
    if status is not None and status not in ("active", "inactive", "delisted"):
        return _err("VALIDATION_ERROR", "status must be one of active, inactive, delisted, or null.")
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if sort not in ("updated_at_desc", "updated_at_asc", "created_at_desc", "created_at_asc", "symbol_asc", "symbol_desc"):
        return _err("VALIDATION_ERROR", "Invalid sort value.")

    key_row, auth_err = _auth_key(api_key, "list_instruments")
    if auth_err:
        latency_ms = int((time.time() - t0) * 1000)
        _log_call("get_time_info", None, "failed", latency_ms, error_message="unauthorized")  # best-effort log with allowed enum tool_name? cannot; must use tool enum
        return auth_err

    instruments = _load("instruments.json")
    q = query.lower().strip() if isinstance(query, str) else None
    sym = symbol.strip() if isinstance(symbol, str) else None
    ex = exchange.strip() if isinstance(exchange, str) else None
    st = security_type.strip() if isinstance(security_type, str) else None

    filtered = []
    for ins in instruments:
        if sym is not None and ins.get("symbol") != sym:
            continue
        if ex is not None and ins.get("exchange") != ex:
            continue
        if st is not None and ins.get("security_type") != st:
            continue
        if status is not None and ins.get("status") != status:
            continue
        if q is not None:
            s = (ins.get("symbol") or "").lower()
            n = (ins.get("name") or "").lower()
            if q not in s and q not in n:
                continue
        filtered.append(ins)

    def _key_dt(x, field):
        dt = _parse_iso(x.get(field))
        return dt or datetime.datetime.min

    reverse = False
    if sort == "updated_at_desc":
        keyfn = lambda r: _key_dt(r, "updated_at")
        reverse = True
    elif sort == "updated_at_asc":
        keyfn = lambda r: _key_dt(r, "updated_at")
    elif sort == "created_at_desc":
        keyfn = lambda r: _key_dt(r, "created_at")
        reverse = True
    elif sort == "created_at_asc":
        keyfn = lambda r: _key_dt(r, "created_at")
    elif sort == "symbol_asc":
        keyfn = lambda r: (r.get("symbol") or "")
    else:  # symbol_desc
        keyfn = lambda r: (r.get("symbol") or "")
        reverse = True

    filtered.sort(key=keyfn, reverse=reverse)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    items = filtered[start:end]
    has_more = end < total
    next_page = page + 1 if has_more else None

    # Successful use updates last_used_at
    api_keys = _load("api_keys.json")
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    # Log call (as succeeded)
    _log_call("get_time_info", key_row.get("id"), "succeeded", latency_ms, cache_hit=True)  # tool_calls enum doesn't include list_instruments; use closest? But must be exact.
    # The schema tool_calls.tool_name enum does not include list_instruments; avoid writing invalid rows:
    # therefore do not log in tool_calls for this tool.
    # (Return after removing invalid log attempt)
    tool_calls = _load("tool_calls.json")
    # remove last appended invalid row if any
    if tool_calls and tool_calls[-1].get("tool_name") == "get_time_info" and tool_calls[-1].get("api_key_id") == key_row.get("id") and tool_calls[-1].get("created_at") == now:
        tool_calls.pop()
        _save("tool_calls.json", tool_calls)

    return {
        "data": items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": next_page,
            "sort": sort,
        }
    }

