    if security_type is not None and (not isinstance(security_type, str) or not security_type.strip()):
        return _err("VALIDATION_ERROR", "security_type must be a non-empty string or null.")
    if currency is not None and (not isinstance(currency, str) or not currency.strip()):
        return _err("VALIDATION_ERROR", "currency must be a non-empty string or null.")

    key_row, auth_err = _auth_key(api_key)
    if auth_err:
        return auth_err

    instruments = _load("instruments.json")

    # Resolve by symbol (unique constraint)
    existing = None
    for ins in instruments:
        if ins.get("symbol") == sym:
            existing = ins
            break

    if existing:
        # Optionally enrich missing fields without changing immutable constraints
        changed = False
        if exchange is not None and existing.get("exchange") != exchange.strip():
            existing["exchange"] = exchange.strip()
            changed = True
        if name is not None and existing.get("name") != name.strip():
            existing["name"] = name.strip()
            changed = True
        if currency is not None and existing.get("currency") != currency.strip():
            existing["currency"] = currency.strip()
            changed = True
        # security_type in schema must be 'stock' only; do not change to invalid values
        if changed:
            existing["updated_at"] = now
            _save("instruments.json", instruments)
        api_keys = _load("api_keys.json")
        for r in api_keys:
            if r.get("id") == key_row.get("id"):
                r["last_used_at"] = now
                r["updated_at"] = now
                break
        _save("api_keys.json", api_keys)
        _ = int((time.time() - t0) * 1000)
        return {"data": existing, "meta": {"created": False}}

    # Create new instrument with status=active; enforce security_type constraint ('stock')
    # Tool param default 'equity' is not allowed by schema; map to 'stock' if provided non-null.
    st = (security_type.strip().lower() if isinstance(security_type, str) else "stock")
    if st not in ("stock", "equity"):
        return _err("VALIDATION_ERROR", "security_type is invalid for this service; expected 'stock'.")
    st = "stock"

    new_row = {
        "id": _new_id("ins"),
        "symbol": sym,
        "exchange": exchange.strip() if isinstance(exchange, str) else None,
        "name": name.strip() if isinstance(name, str) else None,
        "security_type": st,
        "currency": currency.strip() if isinstance(currency, str) else None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Ensure unique(symbol)
    for ins in instruments:
        if ins.get("symbol") == sym:
            return _err("CONFLICT", "Instrument with this symbol already exists.", symbol=sym)

    instruments.append(new_row)
    _save("instruments.json", instruments)

    api_keys = _load("api_keys.json")
    for r in api_keys:
        if r.get("id") == key_row.get("id"):
            r["last_used_at"] = now
            r["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _ = int((time.time() - t0) * 1000)
    return {"data": new_row, "meta": {"created": True}}

def update_instrument(api_key, id, name=None, exchange=None, security_type=None, currency=None, status=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}{uuid.uuid4().hex[:26]}"

    def _parse_iso(s):
        if not s or not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None

    # ---- Validate inputs (schema-consistent; null means "no change")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string or null")
    if exchange is not None and (not isinstance(exchange, str) or not exchange.strip()):
        return _err("VALIDATION_ERROR", "exchange must be a non-empty string or null")
    if security_type is not None and (not isinstance(security_type, str) or not security_type.strip()):
        return _err("VALIDATION_ERROR", "security_type must be a non-empty string or null")
    if currency is not None and (not isinstance(currency, str) or not currency.strip()):
        return _err("VALIDATION_ERROR", "currency must be a non-empty string or null")
    if status is not None:
        if not isinstance(status, str) or status not in {"active", "inactive", "delisted"}:
            return _err("VALIDATION_ERROR", "status must be one of: active, inactive, delisted or null")

    api_key_val = api_key.strip()
    inst_id = id.strip()

    # ---- Load store
    api_keys = _load("api_keys.json")
    instruments = _load("instruments.json")
    tool_calls = _load("tool_calls.json")

    # ---- Authenticate explicit api_key parameter by matching stored id (or client-visible value). Reject revoked.
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key_val:
            key_row = k
            break
    if key_row is None:
        # also allow matching by some client-visible field if present (label is not a credential, but accept if store uses it)
        for k in api_keys:
            if k.get("label") == api_key_val:
                key_row = k
                break
    if key_row is None:
        # log refusal
        call_id = _gen_id("aks_call_")
        tool_calls.append({
            "id": call_id,
            "api_key_id": None,
            "tool_name": "get_time_info",
            "instrument_id": None,
            "symbol": None,
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": None,
            "status": "failed",
            "cache_hit": False,
            "upstream_latency_ms": None,
            "error_message": "unauthorized",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Invalid API key")

    if key_row.get("status") != "active":
        call_id = _gen_id("aks_call_")
        tool_calls.append({
            "id": call_id,
            "api_key_id": key_row.get("id"),
            "tool_name": "get_time_info",
            "instrument_id": None,
            "symbol": None,
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": None,
            "status": "failed",
            "cache_hit": False,
            "upstream_latency_ms": None,
            "error_message": "api key revoked",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "API key is revoked")

    # ---- Rate limit enforcement for this key (observable dynamics)
    rpm = key_row.get("requests_per_minute")
    rpd = key_row.get("requests_per_day")
    if not isinstance(rpm, int) or not isinstance(rpd, int) or rpm < 1 or rpd < 1:
        return _err("VALIDATION_ERROR", "API key limits are misconfigured", api_key_id=key_row.get("id"))

    min_count = 0
    day_count = 0
    for c in tool_calls:
        if c.get("api_key_id") != key_row.get("id"):
            continue
        ts = _parse_iso(c.get("created_at"))
        if not ts:
            continue
        delta = (now - ts).total_seconds()
        if 0 <= delta < 60:
            min_count += 1
        if ts.date() == now.date():
            day_count += 1
    if min_count >= rpm or day_count >= rpd:
        call_id = _gen_id("aks_call_")
        tool_calls.append({
            "id": call_id,
            "api_key_id": key_row.get("id"),
            "tool_name": "get_time_info",
            "instrument_id": None,
            "symbol": None,
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": None,
            "status": "failed",
            "cache_hit": False,
            "upstream_latency_ms": None,
            "error_message": "rate limit exceeded",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_calls.json", tool_calls)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- Find instrument
    idx = None
    for i, r in enumerate(instruments):
        if r.get("id") == inst_id:
            idx = i
            break
    if idx is None:
        # log attempt (as a tool_call for observability; piggyback on allowed tool_name enum)
        call_id = _gen_id("aks_call_")
        tool_calls.append({
            "id": call_id,
            "api_key_id": key_row.get("id"),
            "tool_name": "get_time_info",
            "instrument_id": None,
            "symbol": None,
            "source": None,
            "interval": None,
            "interval_multiplier": None,
            "start_date": None,
            "end_date": None,
            "adjust": None,
            "indicators_list": None,
            "recent_n": None,
            "status": "failed",
            "cache_hit": False,
            "upstream_latency_ms": None,
            "error_message": "instrument not found",
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_calls.json", tool_calls)
        return _err("NOT_FOUND", "Instrument not found", id=inst_id)

    inst = instruments[idx]
    old_status = inst.get("status")

    # ---- Apply updates (null means "no change", not "clear")
    changes = {}

    if name is not None and name != inst.get("name"):
        changes["name"] = name
    if exchange is not None and exchange != inst.get("exchange"):
        changes["exchange"] = exchange
    if security_type is not None:
        # enforce schema constraint: only 'stock'
        if security_type != "stock":
            return _err("VALIDATION_ERROR", "security_type must be 'stock'", security_type=security_type)
        if security_type != inst.get("security_type"):
            changes["security_type"] = security_type
    if currency is not None and currency != inst.get("currency"):
        changes["currency"] = currency

    if status is not None:
        if old_status not in {"active", "inactive", "delisted"}:
            return _err("CONFLICT", "Instrument has invalid stored status; cannot transition", id=inst_id, status=old_status)
        allowed = {
            "active": {"inactive", "delisted"},
            "inactive": {"active", "delisted"},
            "delisted": set()
        }
        if status != old_status:
            if status not in allowed.get(old_status, set()):
                return _err("CONFLICT", "Illegal status transition", id=inst_id, from_status=old_status, to_status=status)
            changes["status"] = status

    # Accept valid request even if it results in no changes: return current instrument (idempotent)
    if changes:
        for k, v in changes.items():
            inst[k] = v
        inst["updated_at"] = now_iso
        instruments[idx] = inst
        _save("instruments.json", instruments)

    # update api key last_used_at for successful authenticated call
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    # record audit tool_call row (use allowed tool_name enum as audit sink)
    call_id = _gen_id("aks_call_")
    tool_calls.append({
        "id": call_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "get_time_info",
        "instrument_id": inst_id,
        "symbol": inst.get("symbol"),
        "source": None,
        "interval": None,
        "interval_multiplier": None,
        "start_date": None,
        "end_date": None,
        "adjust": None,
        "indicators_list": None,
        "recent_n": None,
        "status": "succeeded",
        "cache_hit": True,
        "upstream_latency_ms": None,
        "error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("tool_calls.json", tool_calls)

    return {
        "instrument": inst,
        "meta": {
            "tool_call_id": call_id,
            "updated": bool(changes),
            "changed_fields": sorted(list(changes.keys()))
        }
    }

def list_tool_calls(api_key, tool_name=None, status=None, symbol=None, instrument_id=None, source=None, created_from=None, created_to=None, page=None, page_size=None, sort=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0000000" if __import__("os").path.isdir("./environment_mix/0000000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    allowed_tools = {"get_hist_data", "get_realtime_data", "get_news_data", "get_balance_sheet",
                     "get_income_statement", "get_cash_flow", "get_inner_trade_data", "get_time_info"}
    allowed_status = {"received", "running", "succeeded", "failed"}
    allowed_source = {"eastmoney", "eastmoney_direct", "sina", "xueqiu"}
    allowed_sort = {"created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"}

    if tool_name is not None:
        if not isinstance(tool_name, str) or not tool_name.strip():
            return _err("VALIDATION_ERROR", "tool_name must be a non-empty string or null")
        if tool_name not in allowed_tools:
            return _err("VALIDATION_ERROR", "Invalid tool_name", allowed=list(sorted(allowed_tools)))

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string or null")
        if status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))

    if symbol is not None:
        if not isinstance(symbol, str) or not symbol.strip():
            return _err("VALIDATION_ERROR", "symbol must be a non-empty string or null")

    if instrument_id is not None:
        if not isinstance(instrument_id, str) or not instrument_id.strip():
            return _err("VALIDATION_ERROR", "instrument_id must be a non-empty string or null")

    if source is not None:
        if not isinstance(source, str):
            return _err("VALIDATION_ERROR", "source must be a string or null")
        if source not in allowed_source:
            return _err("VALIDATION_ERROR", "Invalid source", allowed=list(sorted(allowed_source)))

    def _is_yyyy_mm_dd(s):
        if not isinstance(s, str) or len(s) != 10:
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except ValueError:
            return False

    if created_from is not None and not _is_yyyy_mm_dd(created_from):
        return _err("VALIDATION_ERROR", "created_from must be YYYY-MM-DD or null")
    if created_to is not None and not _is_yyyy_mm_dd(created_to):
        return _err("VALIDATION_ERROR", "created_to must be YYYY-MM-DD or null")
    if created_from is not None and created_to is not None and created_from > created_to:
        return _err("VALIDATION_ERROR", "created_from must be <= created_to")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if sort is None:
        sort = "created_at_desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort", allowed=list(sorted(allowed_sort)))

    # ---- Authenticate by api_key against stored api_keys.id or api_keys.key_hash (client-visible value) ----
    api_keys = _load("api_keys.json")
    key_row = None
    for r in api_keys:
        if r.get("id") == api_key or r.get("key_hash") == api_key:
            key_row = r
            break
    if not key_row or key_row.get("status") != "active":
        # Log failed call attempt (not a tool call record; this endpoint itself isn't in tool_calls enum)
        # We still record observable dynamics by updating last_used_at only on success, and not mutating limits on failure.
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    # ---- Enforce rate limits using tool_calls as the request log (observable service dynamics) ----
    tool_calls = _load("tool_calls.json")
    # Use succeeded/failed calls for counting; include running/received too (they are calls).
    def _parse_iso_z(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    now_dt = _parse_iso_z(now)
    if now_dt is None:
        now_dt = datetime.datetime.utcnow().replace(microsecond=0)

    minute_ago = now_dt - datetime.timedelta(seconds=60)
    day_ago = now_dt - datetime.timedelta(days=1)

    rpm = int(key_row.get("requests_per_minute", 1))
    rpd = int(key_row.get("requests_per_day", 1))

    used_min = 0
    used_day = 0
    for c in tool_calls:
        if c.get("api_key_id") != key_row.get("id"):
            continue
        cts = _parse_iso_z(c.get("created_at"))
        if cts is None:
            continue
        if cts >= minute_ago:
            used_min += 1
        if cts >= day_ago:
            used_day += 1

    # This endpoint call itself should count against limits. Refuse if it would exceed.
    if used_min + 1 > rpm:
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, used_in_last_minute=used_min)
    if used_day + 1 > rpd:
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit_per_day=rpd, used_in_last_day=used_day)

    # ---- Query/filter tool_calls ----
    rows = tool_calls

    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if symbol is not None:
        rows = [r for r in rows if r.get("symbol") == symbol]
    if instrument_id is not None:
        rows = [r for r in rows if r.get("instrument_id") == instrument_id]
    if source is not None:
        rows = [r for r in rows if r.get("source") == source]

    if created_from is not None or created_to is not None:
        cf = created_from
        ct = created_to
        def _date_part(ts):
            if not isinstance(ts, str) or len(ts) < 10:
                return None
            return ts[:10]
        filtered = []
        for r in rows:
            d = _date_part(r.get("created_at"))
            if d is None:
                continue
            if cf is not None and d < cf:
                continue
            if ct is not None and d > ct:
                continue
            filtered.append(r)
        rows = filtered

    # ---- Sort ----
    def _k(ts):
        if ts is None:
            return ""
        return ts

    reverse = sort.endswith("_desc")
    if sort.startswith("created_at_"):
        rows.sort(key=lambda r: _k(r.get("created_at")), reverse=reverse)
    else:
        rows.sort(key=lambda r: _k(r.get("updated_at")), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # ---- Update key last_used_at on success ----
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    # ---- Return envelope ----
    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "sort": sort,
            "rate_limit": {
                "requests_per_minute": rpm,
                "requests_per_day": rpd,
                "used_in_last_minute": used_min + 1,
                "used_in_last_day": used_day + 1
            },
            "latency_ms": latency_ms
        }
    }

