        return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=rpm, used_in_last_minute=used_min)
    if used_day + 1 > rpd:
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit_per_day=rpd, used_in_last_day=used_day)

    # Successful auth updates last_used_at.
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": {
            "api_key": {
                "id": key_row.get("id"),
                "label": key_row.get("label"),
                "status": key_row.get("status"),
                "created_at": key_row.get("created_at"),
                "updated_at": key_row.get("updated_at"),
                "last_used_at": key_row.get("last_used_at"),
                "limits": {
                    "requests_per_minute": rpm,
                    "requests_per_day": rpd
                }
            },
            "scopes": [
                "get_hist_data",
                "get_realtime_data",
                "get_news_data",
                "get_balance_sheet",
                "get_income_statement",
                "get_cash_flow",
                "get_inner_trade_data",
                "get_time_info",
                "list_tool_calls",
                "get_whoami"
            ],
            "usage": {
                "used_in_last_minute": used_min + 1,
                "used_in_last_day": used_day + 1
            }
        },
        "meta": {
            "latency_ms": latency_ms,
            "as_of": now
        }
    }
